#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: deploy the wishlist to production on this host.
#
# Order matters: checks, tests, and a verified database snapshot run before
# anything changes; the new system is built before it is switched to; the API
# is verified before the site is pushed. Any failure after the switch restores
# the database snapshot and the previous system generation.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

REPO_ROOT=$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)
PROD_DB=/var/lib/wishlist/wishes.db
NIXOS_DIR=/etc/nixos
FLAKE="$NIXOS_DIR#mainframe"
PUBLIC_API=https://wishlist-api.oliveirarleo.com
PUBLIC_SITE=https://oliveirarleo.com/wishlist/
SERVICE_ENV=/run/secrets/rendered/wishlist.env

TOTAL_STAGES=7

SWITCHED=0
BACKUP_PATH=""
PREV_GENERATION=""
BEFORE_COUNTS=""
BEFORE_WISHES=""
BEFORE_USERS=""
AHEAD=0
PUSHED=0

banner "Wishlist production deploy"

die() { printf '\n  %s✗ %s%s\n\n' "$YELLOW" "$1" "$RESET"; exit 1; }

# Counts on any database file; "n/a" for tables this generation does not have.
db_counts_at() {
  node -e '
    const { DatabaseSync } = require("node:sqlite");
    const db = new DatabaseSync(process.argv[1], { readOnly: true });
    const n = (sql) => { try { return db.prepare(sql).get().n; } catch { return "n/a"; } };
    console.log(
      `wishes=${n("select count(*) n from wishes")}` +
      ` users=${n("select count(*) n from users")}` +
      ` migrations=${n("select count(*) n from __drizzle_migrations")}` +
      ` legacy=${n("select count(*) n from legacy_wishlist_secrets")}`,
    );
    db.close();
  ' "$1"
}
db_counts() { db_counts_at "$PROD_DB"; }
count_of() { tr ' ' '\n' <<<"$2" | sed -n "s/^$1=//p" | head -1; }

db_backup() {
  node -e '
    const { DatabaseSync, backup } = require("node:sqlite");
    const src = process.argv[1];
    const dest = process.argv[2];
    (async () => {
      const db = new DatabaseSync(src, { readOnly: true });
      await backup(db, dest);
      db.close();
    })().catch((error) => { console.error(error.message); process.exit(1); });
  ' "$PROD_DB" "$1"
}

wait_for_api() {
  local tries="${1:-30}" i
  for ((i = 1; i <= tries; i++)); do
    if curl -fsS --max-time 3 "$PUBLIC_API/api/health" >/dev/null 2>&1; then return 0; fi
    sleep 1
  done
  return 1
}

stop_service() { sudo systemctl stop wishlist 2>/dev/null || true; }
start_service() { sudo systemctl start wishlist 2>/dev/null || true; }

restore_database() {
  [[ -n "$BACKUP_PATH" && -f "$BACKUP_PATH" ]] || { warn "no verified snapshot to restore"; return 1; }
  stop_service
  if systemctl is-active --quiet wishlist; then
    warn "wishlist.service is still active; not restoring over a live database"
    return 1
  fi
  cp -f "$BACKUP_PATH" "$PROD_DB" || return 1
  rm -f "${PROD_DB}-wal" "${PROD_DB}-shm"
  chmod 600 "$PROD_DB"
}

rollback() {
  local why="$1"
  set +e
  trap - ERR
  printf '\n  %s↩ Rolling back: %s%s\n' "$YELLOW" "$why" "$RESET"
  note "database snapshot and previous system generation are the restore points"

  if restore_database; then
    note "database restored from $BACKUP_PATH"
  else
    warn "database restore FAILED; the snapshot is still at $BACKUP_PATH"
  fi

  if [[ -n "$PREV_GENERATION" ]]; then
    if sudo nixos-rebuild switch --rollback >/dev/null 2>&1; then
      note "system rolled back to $(basename "$PREV_GENERATION")"
    else
      warn "nixos-rebuild switch --rollback failed; run it by hand"
    fi
  fi

  start_service
  if wait_for_api 45; then
    note "API healthy again: $(db_counts)"
  else
    warn "API is NOT healthy after rollback; check: sudo systemctl status wishlist"
  fi

  printf '\n  %sRollback finished.%s  %sRe-run the deploy after fixing the cause.%s\n' "$BOLD" "$RESET" "$DIM" "$RESET"
  printf '  %sSnapshot kept at %s%s\n\n' "$DIM" "$BACKUP_PATH" "$RESET"
  exit 1
}

on_error() {
  local code="$1"
  set +e
  if (( SWITCHED )); then
    rollback "command failed with exit $code"
  fi
  printf '\n  %s✗ Deploy stopped (exit %s). The running system was not changed.%s\n\n' "$YELLOW" "$code" "$RESET"
  exit "$code"
}
trap 'on_error $?' ERR

[[ -f "$NIXOS_DIR/flake.nix" ]] || die "Run this on the NixOS server: $NIXOS_DIR/flake.nix is missing."
[[ -f "$PROD_DB" ]] || die "Production database not found at $PROD_DB."
command -v node >/dev/null || die "node is required."
cd "$REPO_ROOT"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Preflight"
say "Reading the checkout and the running service. Nothing changes here."
[[ "$(git rev-parse --abbrev-ref HEAD)" == "main" ]] || \
  die "Switch to main first (currently on $(git rev-parse --abbrev-ref HEAD))."
[[ -z "$(git status --porcelain)" ]] || die "Commit or stash the working tree first."
git fetch --quiet origin main
AHEAD=$(git rev-list --count origin/main..main)
PREV_GENERATION=$(readlink -f /run/current-system)
BEFORE_COUNTS=$(db_counts)
BEFORE_WISHES=$(count_of wishes "$BEFORE_COUNTS")
BEFORE_USERS=$(count_of users "$BEFORE_COUNTS")
[[ "$BEFORE_WISHES" =~ ^[0-9]+$ && "$BEFORE_USERS" =~ ^[0-9]+$ ]] || \
  die "Could not read wishes and users from $PROD_DB."

note "repo:            $REPO_ROOT"
note "rollback point:  $(basename "$PREV_GENERATION")"
note "database:        $BEFORE_COUNTS"
note "commits ahead:   $AHEAD"

if (( AHEAD )); then
  say "These commits would reach origin/main:"
  git log --oneline origin/main..main | sed 's/^/      /'
else
  note "No local commits ahead; the push stage will be a no-op."
fi

legacy=$(count_of legacy "$BEFORE_COUNTS")
if [[ "$legacy" =~ ^[0-9]+$ ]] && (( legacy > 0 )); then
  note "$legacy account(s) still upgrade their old secret on first sign-in."
  if [[ -f "$SERVICE_ENV" ]] && ! grep -q '^WISHLIST_SECRET_PEPPER=' "$SERVICE_ENV"; then
    warn "WISHLIST_SECRET_PEPPER is missing from $SERVICE_ENV; those accounts cannot sign in."
  fi
fi
pause "Press Enter to run checks and tests"

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Checks and tests"
say "Type-check the Astro app and run the full Vitest suite. A failure stops here,"
say "before production is touched."
pnpm exec astro check
pnpm test
note "checks and tests passed"
pause "Press Enter to take the database snapshot"

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Back up production"
mkdir -p /var/lib/wishlist/backups
BACKUP_PATH="/var/lib/wishlist/backups/wishes-$(date -u +%Y%m%dT%H%M%SZ)-pre-deploy.db"
say "Writing an online snapshot with SQLite's backup API and verifying it."
db_backup "$BACKUP_PATH"
chmod 600 "$BACKUP_PATH"

node -e '
  const { DatabaseSync } = require("node:sqlite");
  const db = new DatabaseSync(process.argv[1], { readOnly: true });
  const result = db.prepare("pragma integrity_check").get().integrity_check;
  db.close();
  if (result !== "ok") { console.error(`integrity_check: ${result}`); process.exit(1); }
' "$BACKUP_PATH" || die "The snapshot did not pass integrity_check."

BACKUP_COUNTS=$(db_counts_at "$BACKUP_PATH")
note "snapshot: $BACKUP_PATH"
note "snapshot: $BACKUP_COUNTS"
[[ "$(count_of wishes "$BACKUP_COUNTS")" == "$BEFORE_WISHES" ]] || die "Snapshot wishes do not match the live database."
[[ "$(count_of users "$BACKUP_COUNTS")" == "$BEFORE_USERS" ]] || die "Snapshot users do not match the live database."
note "snapshot verified: integrity ok, wishes and users match live"
pause "Press Enter to refresh the flake input and build"

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Update the flake input and build"
say "The NixOS flake pins this repository by path, so refresh the lock first."
( cd "$NIXOS_DIR" && sudo nix flake update wishlist )
note "$(grep -A8 '"wishlist"' "$NIXOS_DIR/flake.lock" | grep -m1 lastModified || true)"
say "Building the new system without touching the running one."
sudo nixos-rebuild build --flake "$FLAKE"
note "build succeeded; the running system is unchanged"
pause "Press Enter to switch production"

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Switch and verify"
say "This restarts the API and applies pending migrations."
note "rollback = restore $BACKUP_PATH + $(basename "$PREV_GENERATION")"
if ! confirm "Switch the server to the new generation now?"; then
  die "Cancelled before the switch; production is unchanged."
fi

SWITCHED=1
sudo nixos-rebuild switch --flake "$FLAKE"

say "Waiting for the API to report healthy (up to 60s)..."
wait_for_api 60 || rollback "the API did not become healthy after the switch"
note "health: $(curl -fsS --max-time 5 "$PUBLIC_API/api/health")"

AFTER_COUNTS=$(db_counts)
AFTER_WISHES=$(count_of wishes "$AFTER_COUNTS")
AFTER_USERS=$(count_of users "$AFTER_COUNTS")
note "database: $AFTER_COUNTS"
[[ "$AFTER_WISHES" =~ ^[0-9]+$ ]] || rollback "could not read wishes after the switch"
(( AFTER_WISHES >= BEFORE_WISHES )) || rollback "wishes dropped from $BEFORE_WISHES to $AFTER_WISHES"
(( AFTER_USERS >= BEFORE_USERS )) || rollback "users dropped from $BEFORE_USERS to $AFTER_USERS"

systemctl is-active --quiet wishlist || rollback "wishlist.service is not active"
systemctl list-timers wishlist-backup --all --no-pager | grep -q wishlist-backup || \
  warn "wishlist-backup.timer is missing; the daily snapshot will not run"
note "service running: $(systemctl show wishlist -p ExecStart --value | sed 's/.*path=\([^ ]*\).*/\1/')"

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Push and deploy the site"
AHEAD=$(git rev-list --count origin/main..main)
if (( AHEAD == 0 )); then
  note "nothing to push"
else
  say "The API is healthy, so the frontend can go live."
  if ! confirm "Push $(git rev-parse --short HEAD) to origin/main?"; then
    warn "Not pushed. The server stays on the new generation and the site stays old."
    SKIPPED+=("git push origin main")
  else
    git push origin main
    PUSHED=1
    note "pushed $(git rev-parse --short HEAD)"
  fi
fi

if (( PUSHED )) && command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
  head_sha=$(git rev-parse HEAD)
  run_id=""
  for _ in $(seq 1 12); do
    run_id=$(gh run list --limit 10 --json databaseId,headSha \
      --jq ".[] | select(.headSha==\"$head_sha\") | .databaseId" 2>/dev/null | head -1 || true)
    [[ -n "$run_id" ]] && break
    sleep 5
  done
  if [[ -n "$run_id" ]]; then
    say "Waiting for the Pages workflow $run_id..."
    if gh run watch "$run_id" --exit-status >/dev/null 2>&1; then
      note "Pages workflow succeeded"
    else
      warn "Pages workflow failed: https://github.com/oliveirarleo/oliveirarleo.github.io/actions/runs/$run_id"
      if confirm "Roll the server back to match the old site?"; then
        rollback "the Pages deploy failed after the API switch"
      fi
      SKIPPED+=("re-run the Pages workflow from the Actions tab")
    fi
  else
    SKIPPED+=("no Pages workflow found for $head_sha; check the Actions tab")
  fi
fi

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Done"
SWITCHED=0
trap - ERR
note "commit:      $(git rev-parse --short HEAD) ($(git rev-parse --abbrev-ref HEAD))"
note "generation:  $(readlink -f /run/current-system)"
note "database:    $(db_counts)"
note "snapshot:    $BACKUP_PATH"
note "manual rollback: sudo nixos-rebuild switch --rollback"
printf '\n'
finish
}

run_wizard "$@"; exit
